CREATE TYPE "Plan" AS ENUM ('FREE','PRO','ENTERPRISE');
CREATE TYPE "UserStatus" AS ENUM ('ACTIVE','INVITED','SUSPENDED');
CREATE TYPE "StockMovementType" AS ENUM ('PURCHASE','SALE','ADJUSTMENT_IN','ADJUSTMENT_OUT','LOSS','EXPIRATION','RETURN','TRANSFER_IN','TRANSFER_OUT','INVENTORY_CORRECTION','RESERVATION','RELEASE');
CREATE TYPE "AuditAction" AS ENUM ('CREATE','UPDATE','DELETE','LOGIN','LOGOUT','STATUS_CHANGE','PAYMENT_EVENT','STOCK_MOVEMENT');

CREATE TABLE "Tenant" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(), "name" TEXT NOT NULL, "slug" TEXT NOT NULL UNIQUE, "plan" "Plan" NOT NULL DEFAULT 'FREE', "createdAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Store" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(), "tenantId" UUID NOT NULL, "name" TEXT NOT NULL, "slug" TEXT NOT NULL, "timezone" TEXT NOT NULL DEFAULT 'America/Recife', "active" BOOLEAN NOT NULL DEFAULT TRUE, "createdAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Store_tenantId_fkey" FOREIGN KEY ("tenantId") REFERENCES "Tenant"("id") ON DELETE RESTRICT ON UPDATE CASCADE, UNIQUE("tenantId","slug"));
CREATE INDEX "Store_tenantId_idx" ON "Store"("tenantId");
CREATE TABLE "User" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(), "tenantId" UUID NOT NULL, "email" TEXT NOT NULL, "passwordHash" TEXT NOT NULL, "displayName" TEXT NOT NULL, "role" TEXT NOT NULL, "status" "UserStatus" NOT NULL DEFAULT 'ACTIVE', "mfaEnabled" BOOLEAN NOT NULL DEFAULT FALSE, "createdAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "User_tenantId_fkey" FOREIGN KEY ("tenantId") REFERENCES "Tenant"("id") ON DELETE RESTRICT ON UPDATE CASCADE, UNIQUE("tenantId","email"));
CREATE INDEX "User_tenantId_status_idx" ON "User"("tenantId","status");
CREATE TABLE "Product" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(), "tenantId" UUID NOT NULL, "gtin" TEXT, "name" TEXT NOT NULL, "category" TEXT, "unit" TEXT NOT NULL, "active" BOOLEAN NOT NULL DEFAULT TRUE, "createdAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Product_tenantId_fkey" FOREIGN KEY ("tenantId") REFERENCES "Tenant"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE INDEX "Product_tenantId_name_idx" ON "Product"("tenantId","name");
CREATE INDEX "Product_tenantId_gtin_idx" ON "Product"("tenantId","gtin");
CREATE TABLE "ProductStore" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(), "productId" UUID NOT NULL, "storeId" UUID NOT NULL, "costPrice" DECIMAL(14,4), "salePrice" DECIMAL(14,4), "minimumQty" DECIMAL(14,3), "maximumQty" DECIMAL(14,3), "reorderPoint" DECIMAL(14,3), CONSTRAINT "ProductStore_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Product"("id") ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT "ProductStore_storeId_fkey" FOREIGN KEY ("storeId") REFERENCES "Store"("id") ON DELETE CASCADE ON UPDATE CASCADE, UNIQUE("productId","storeId"));
CREATE TABLE "StockBalance" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(), "tenantId" UUID NOT NULL, "storeId" UUID NOT NULL, "productId" UUID NOT NULL, "physicalQuantity" DECIMAL(14,3) NOT NULL DEFAULT 0, "reservedQuantity" DECIMAL(14,3) NOT NULL DEFAULT 0, "updatedAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "StockBalance_storeId_fkey" FOREIGN KEY ("storeId") REFERENCES "Store"("id") ON DELETE RESTRICT ON UPDATE CASCADE, CONSTRAINT "StockBalance_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Product"("id") ON DELETE RESTRICT ON UPDATE CASCADE, UNIQUE("storeId","productId"));
CREATE INDEX "StockBalance_tenantId_productId_idx" ON "StockBalance"("tenantId","productId");
CREATE TABLE "StockMovement" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(), "tenantId" UUID NOT NULL, "storeId" UUID NOT NULL, "productId" UUID NOT NULL, "type" "StockMovementType" NOT NULL, "quantity" DECIMAL(14,3) NOT NULL, "quantityBefore" DECIMAL(14,3) NOT NULL, "quantityAfter" DECIMAL(14,3) NOT NULL, "reason" TEXT, "reference" TEXT, "actorUserId" UUID, "createdAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "StockMovement_storeId_fkey" FOREIGN KEY ("storeId") REFERENCES "Store"("id") ON DELETE RESTRICT ON UPDATE CASCADE, CONSTRAINT "StockMovement_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Product"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE INDEX "StockMovement_tenantId_storeId_productId_createdAt_idx" ON "StockMovement"("tenantId","storeId","productId","createdAt");
CREATE TABLE "AuditLog" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(), "tenantId" UUID NOT NULL, "actorId" UUID, "action" "AuditAction" NOT NULL, "entityType" TEXT NOT NULL, "entityId" TEXT, "before" JSONB, "after" JSONB, "requestId" TEXT, "createdAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "AuditLog_tenantId_fkey" FOREIGN KEY ("tenantId") REFERENCES "Tenant"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE INDEX "AuditLog_tenantId_entityType_entityId_createdAt_idx" ON "AuditLog"("tenantId","entityType","entityId","createdAt");
